"""Entrées autonomes des six expériences : modèle, notations et premiers essais."""
def guide(purpose,objects,hypotheses,techniques,steps,sup,spe,beyond,expected):
    return dict(purpose=purpose,objects=objects.split(' | '),hypotheses=hypotheses.split(' | '),
                techniques=techniques.split(' | '),first_steps=steps,
                levels=dict(sup=sup,spe=spe,beyond=beyond),expected=expected)

